  execSync(`bun run ${toolName}`);
  console.log(`[RESULT] ${toolName} succeeded.`);
} catch (error) {
  console.error(`[RESULT] ${toolName} failed.`);
  console.error(error.message);
  process.exit(1);
}
EOF

